-- notion_mock seed
BEGIN;
-- English business textfamily officeEnglish business textitemEnglish business text；English business textitemEnglish business text、English business text、statusEnglish business textreviewEnglish business text。
UPDATE pages
SET page_id = REPLACE(page_id, 'pg_noise_', 'pg_archive_'),
    title = CASE CAST(substr(page_id,-3) AS INTEGER) % 7
      WHEN 0 THEN 'English business textaccountEnglish business textanomalycash flowEnglish business text'
      WHEN 1 THEN 'English business textholdings、English business textriskEnglish business text'
      WHEN 2 THEN 'core retail propertiesEnglish business text、English business texttaxes and feesEnglish business text'
      WHEN 3 THEN 'Tang Precision Manufacturingcredit facilityEnglish business textaccounts receivableEnglish business text'
      WHEN 4 THEN 'English business textdisclosure、English business textitemEnglish business text'
      WHEN 5 THEN 'English business textitemEnglish business text、English business text'
      ELSE 'English business text、authorizationEnglish business textitemEnglish business text'
    END || ' · English business text ' || substr(page_id,-3),
    properties_json = json_object(
      'archive_batch', substr(page_id,-3),
      'review_month', substr(created_time,1,7),
      'owner', CASE CAST(substr(page_id,-3) AS INTEGER) % 4 WHEN 0 THEN 'operations' WHEN 1 THEN 'investment' WHEN 2 THEN 'legal' ELSE 'tax' END,
      'status', CASE CAST(substr(page_id,-3) AS INTEGER) % 3 WHEN 0 THEN 'closed' WHEN 1 THEN 'monitor' ELSE 'pending_review' END,
      'next_review', date(substr(created_time,1,10), '+' || (CAST(substr(page_id,-3) AS INTEGER) % 45 + 15) || ' day')
    )
WHERE page_id LIKE 'pg_noise_%';
COMMIT;
